DIRS = 'NESW'
STEP = {'N': (0, 1), 'E': (1, 0), 'S': (0, -1), 'W': (-1, 0)}

def solution(spec):
    lines = [ln.strip() for ln in spec.strip().split('\n') if ln.strip()]
    w, h = map(int, lines[0].split())        # cells are 0..w-1 by 0..h-1
    out = []
    for i in range(1, len(lines), 2):
        x, y, d = lines[i].split()
        x, y = int(x), int(y)
        for c in lines[i + 1] if i + 1 < len(lines) else '':
            if c in 'LR':
                d = DIRS[(DIRS.index(d) + (1 if c == 'R' else -1)) % 4]
            elif c in 'FB':
                dx, dy = STEP[d]
                if c == 'B':
                    dx, dy = -dx, -dy
                x, y = (x + dx) % w, (y + dy) % h   # the planet is round: wrap
        out.append(f'{x} {y} {d}')
    return '\n'.join(out)
